from typing import Callable

def validar_email(s: str) -> bool:
    return "@" in s and "." in s.split("@")[-1]

def validar_telefono(s: str) -> bool:
    return s.replace("-", "").replace("+", "").isdigit()

def validar(valor: str, estrategia: Callable[[str], bool]) -> bool:
    return estrategia(valor)

print(validar("user@mail.com", validar_email))  # True
print(validar("+54-911-1234", validar_telefono))  # True

# Observer con events dict (pythónico)
from collections import defaultdict
from typing import Callable

class EventBus:
    def __init__(self):
        self._handlers: dict = defaultdict(list)

    def on(self, evento: str, handler: Callable) -> None:
        self._handlers[evento].append(handler)

    def emit(self, evento: str, **datos) -> None:
        for handler in self._handlers[evento]:
            handler(**datos)

bus = EventBus()

@bus.on("login")
def log_login(usuario, **_):
    print(f"Usuario {usuario} inició sesión")

bus.emit("login", usuario="ana", ip="192.168.1.1")

